@using sv_387bd742f6b54dda82467c8992f6de7a.Services

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="entry-wrapper">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm
                Name="@References[index].Name"
                NameChanged="@(v => UpdateRef(index, r => r with { Name = v }))"
                Relationship="@References[index].Relationship"
                RelationshipChanged="@(v => UpdateRef(index, r => r with { Relationship = v }))"
                Email="@References[index].Email"
                EmailChanged="@(v => UpdateRef(index, r => r with { Email = v }))"
                Phone="@References[index].Phone"
                PhoneChanged="@(v => UpdateRef(index, r => r with { Phone = v }))"
                CanRemove="@(References.Count > 2)"
                OnRemove="@(() => RemoveRef(index))" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddRef">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="validation-summary">@validationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }

    private string? validationError;

    private void UpdateRef(int index, Func<ReferenceModel, ReferenceModel> update)
    {
        References[index] = update(References[index]);
        ReferencesChanged.InvokeAsync(References);
    }

    private void AddRef()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
            ReferencesChanged.InvokeAsync(References);
        }
    }

    private void RemoveRef(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
            ReferencesChanged.InvokeAsync(References);
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        if (References.Count < 2)
        {
            validationError = "At least 2 references are required.";
            return;
        }

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
            string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone)))
        {
            validationError = "All reference fields are required.";
            return;
        }

        var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        await OnNext.InvokeAsync(refs);
    }

    public record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

