@page "/apply"
@using sv_387bd742f6b54dda82467c8992f6de7a.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   StepNames="stepNames"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              ApplicationService="ApplicationService"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries"
                             EntriesChanged="@(e => workEntries = e)"
                             OnBack="GoBack"
                             OnNext="HandleWorkNext" />
            break;
        case 2:
            <ReferencesStep References="referenceModels"
                            ReferencesChanged="@(r => referenceModels = r)"
                            OnBack="GoBack"
                            OnNext="HandleReferencesNext" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="@(v => coverLetter = v)"
                             OnBack="GoBack"
                             OnNext="HandleCoverLetterNext" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo!"
                        Work="workHistory!"
                        References="references"
                        CoverLetter="@coverLetter"
                        ApplicationService="ApplicationService"
                        OnBack="GoBack"
                        OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private static readonly IReadOnlyList<string> stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";
    private PersonalInfo? personalInfo;

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = [new()];
    private WorkHistory? workHistory;

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> referenceModels = [new(), new()];
    private List<Reference> references = [];

    // Step 4 state
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        if (step == currentStep) return;
        if (completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(WorkHistory work)
    {
        workHistory = work;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }
}

