    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-wrapper {
    margin-bottom: 1rem;
}

.entry-wrapper h4 {
    color: #495057;
    margin-bottom: 0.5rem;
    font-size: 1rem;
}

