.review-dates {
    font-size: 0.875rem;
    color: #6c757d;
}

.review-description {
    margin: 0.25rem 0 0;
    color: #555;
    font-size: 0.9rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #e9ecef;
}

