+.review-header h3 {
+    margin: 0;
+    font-size: 1.1rem;
+    border: none;
+    padding: 0;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #6c757d;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-entry {
+    padding: 0.5rem 0;
+}
+
+.review-entry + .review-entry {
+    border-top: 1px solid #f0f0f0;
+}
+
+.review-dates {
+    font-size: 0.875rem;
+    color: #6c757d;
+}
+
+.review-description {
+    margin: 0.25rem 0 0;
+    color: #555;
+    font-size: 0.9rem;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    border: 1px solid #e9ecef;
+}
+
+/* Submission confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.submission-confirmation h3 {
+    color: #198754;
+    border: none;
+    padding: 0;
+}
+
+@media (max-width: 600px) {
+    .form-row {
+        grid-template-columns: 1fr;
+    }
+
+    .step-indicator {
+        gap: 0.125rem;
+    }
+
+    .step {
+        min-width: 60px;
+        padding: 0.25rem;
+    }
+
+    .step-label {
+        font-size: 0.625rem;
+    }
+
+    .step-connector {
+        width: 15px;
+    }
+}
